def sections_html(sections):
    return ''.join('<h2>'+html.escape(title)+'</h2>'+''.join('<p>'+html.escape(p)+'</p>' for p in paragraphs) for title,paragraphs in sections)

def fields_html(title,fields):
    return '<h2>'+html.escape(title)+'</h2>'+''.join('<h3>'+html.escape(k)+'</h3><p>'+html.escape(v)+'</p>' for k,v in fields)

def contract_terms():
    return sections_html(CONTRACT)

def policy_html():
    return sections_html(POLICY)+fields_html('Приложение 1 Реестр инфраструктуры и сроков',POLICY_REGISTER)
